           ('#999005', 1, 3),
           ('#999006', 1, 2)
         ) AS v(appeal_id, version, n_positions)
    LEFT JOIN public.kp_sets s ON s.appeal_id = v.appeal_id AND s.version = v.version
   WHERE s.id IS NULL
      OR NOT (s.payload ? 'positions')
      OR (CASE WHEN jsonb_typeof(s.payload -> 'positions') = 'array' THEN jsonb_array_length(s.payload -> 'positions') END) IS DISTINCT FROM v.n_positions;
  SELECT bool_or(updated_at < timestamptz '2026-01-01 00:00:00+03') INTO usn_ok FROM public.kp_sets WHERE appeal_id = '#999002' AND version = 1;
  SELECT bool_or(updated_at >= timestamptz '2026-01-01 00:00:00+03') INTO main_ok FROM public.kp_sets WHERE appeal_id = '#999001' AND version = 1;
  IF n_rows <> 7 OR n_bad <> 0 OR usn_ok IS NOT TRUE OR main_ok IS NOT TRUE THEN
    RAISE EXCEPTION 'kp_sets_sample: комплектов % (нужно 7), с неверным числом позиций % (нужно 0), #999002 с датой до 2026 года: % (нужно true), #999001 с датой с 2026 года: % (нужно true)', n_rows, n_bad, usn_ok, main_ok;
  END IF;
END $$;

COMMIT;
